aderModule -->\n\nFileUploader->FileUploaderModule\n\n\n\n\n\nIconDirective\n\nIconDirective\n\nFileUploaderModule -->\n\nIconDirective->FileUploaderModule\n\n\n\n\n\nLoadingModule\n\nLoadingModule\n\nFileUploaderModule -->\n\nLoadingModule->FileUploaderModule\n\n\n\n\n\nFileComponent \n\nFileComponent \n\nFileComponent  -->\n\nFileUploaderModule->FileComponent \n\n\n\n\n\nFileUploader \n\nFileUploader \n\nFileUploader  -->\n\nFileUploaderModule->FileUploader \n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/file-uploader/file-uploader.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Imports\n                    \n                        \n                            FileComponent\n                        \n                        \n                            FileUploader\n                        \n                        \n                            IconDirective\n                        \n                        \n                            LoadingModule\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            FileComponent\n                        \n                        \n                            FileUploader\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from \"@angular/core\";\nimport { CommonModule } from \"@angular/common\";\n\nimport { FileUploader } from \"./file-uploader.component\";\nimport { FileComponent } from \"./file.component\";\n\nimport { LoadingModule } from \"carbon-components-angular/loading\";\nimport { IconDirective } from \"carbon-components-angular/icon\";\n\n@NgModule({\n\texports: [FileUploader, FileComponent],\n\timports: [\n\t\tCommonModule,\n\t\tLoadingModule,\n\t\tIconDirective,\n\t\tFileUploader,\n\t\tFileComponent\n\t]\n})\nexport class FileUploaderModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"directives/GridDirective.html":{"url":"directives/GridDirective.html","title":"directive - GridDirective","body":"\n                   \n\n\n\n\n\n\n\n\n  Directives\n  GridDirective\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            src/grid/grid.directive.ts\n        \n\n\n            \n                Description\n            \n            \n                Get started with importing the directives:\nExample :import {\n    GridDirective,\n    ColumnDirective,\n    RowDirective\n} from 'carbon-components-angular';See demo\n\n            \n\n\n            \n                Implements\n            \n            \n                        OnInit\n                        OnDestroy\n            \n\n\n        \n            Metadata\n            \n                \n                    \n                        Providers\n                        \n                            \n                                {\n    provide: GridService, deps: [[new Optional(), new SkipSelf(), GridService]], useFactory: (parentService: GridService) => {\n        return parentService || new GridService();\n    }\n}\n                            \n                        \n                    \n\n                    \n                        Selector\n                        [cdsGrid], [ibmGrid]\n                    \n\n                    \n                        Standalone\n                        true\n                    \n\n\n\n                \n            \n        \n\n            \n    Index\n    \n        \n                \n          